// TestEncodedSDRHeadersAndAccessUnits проверяет реальные профили, плоскости, глубину и цветовые поля CICP,
// независимый старт и точное сохранение конфигурации/AU через Inspector и неизменяемый Packet.
func TestEncodedSDRHeadersAndAccessUnits(t *testing.T) {
	// fixture выбирает отдельный реально декодированный профиль без зависимости от каталога настроек кодировщика.
	for _, fixture := range encodedSDRFixtures() {
		t.Run(string(fixture.codec)+"/"+fixture.profile+"/"+fixture.pixel, func(t *testing.T) {
			// Подтест сверяет независимые ожидаемые параметры с заголовками выбранного эталона fixture.
			// headers и err содержат исходную конфигурацию и возможную ошибку hex-эталона.
			headers, err := hex.DecodeString(fixture.config)
			if err != nil {
				t.Fatal(err)
			}
			// au содержит исходную полную единицу доступа.
			au, err := hex.DecodeString(fixture.au)
			if err != nil {
				t.Fatal(err)
			}
			// beforeHeaders и beforeAU проверяют, что ни один парсер не изменяет входные байты.
			beforeHeaders, beforeAU := bytes.Clone(headers), bytes.Clone(au)
			// actual хранит результат независимого от транспорта разбора; key подтверждает случайный доступ.
			var actual core.VideoFormat
			var key bool
			if fixture.codec == core.CodecAV1 {
				actual, key, err = InspectAV1TU(headers, au, core.FrameRate{Numerator: 30, Denominator: 1})
			} else {
				// desc связывает реальные avcC с независимо известными размерами кадра.
				desc := VideoDescription{Headers: headers, Width: 128, Height: 128}
				actual, err = H264Format(desc)
				if err == nil {
					key, err = InspectH264AU(desc, au)
				}
			}
			if err != nil {
				t.Fatal(err)
			}
			// color содержит ожидаемую сигнализацию трёх независимых CICP-таблиц.
			color := core.ColorInfo{Range: "limited", Primaries: "bt470m", Transfer: "gamma22", Matrix: "fcc"}
			if !key || actual.CodecProfile != fixture.profile || actual.PixelFormat != fixture.pixel || actual.BitDepth != fixture.depth || actual.Width != 128 || actual.Height != 128 || !actual.FrameRate.Equal(core.FrameRate{Numerator: 30, Denominator: 1}) || actual.Color != color {
				t.Fatalf("Реальный поток: %+v key=%v", actual, key)
			}
			// config сохраняет фактический формат и исходные заголовки с отдельной копией данных.
			config, err := media.NewCodecConfig(media.CodecConfigInfo{Track: media.TrackVideo, SourceEpoch: 2, Revision: 3, TimeBase: media.TimeBase{Numerator: 1, Denominator: 30}, Video: actual}, headers)
			if err != nil {
				t.Fatal(err)
			}
			// packet сохраняет исходный AU; независимость должна определяться данными, а не ложным Keyframe.
			packet, err := media.NewPacket(media.PacketInfo{PTS: -1, DTS: -1, DurationTicks: 1}, config, au)
			if err != nil {
				t.Fatal(err)
			}
			// inspector проверяет фактическое описание без ограничений прежнего каталога кодировщиков.
			var inspector Inspector
			key, err = inspector.Inspect(packet)
			if err != nil || !key || !bytes.Equal(headers, beforeHeaders) || !bytes.Equal(au, beforeAU) || !bytes.Equal(packet.Payload(), beforeAU) || !bytes.Equal(packet.Config().Headers(), beforeHeaders) {
				t.Fatal("Потеря данных либо несовместимость actual", key, err)
			}
			actual.BitDepth = 8
			if fixture.depth == 8 {
				actual.BitDepth = 10
			}
			// mismatch содержит ложную глубину при прежних неизменённых заголовках.
			mismatch, err := media.NewCodecConfig(media.CodecConfigInfo{Track: media.TrackVideo, SourceEpoch: 2, Revision: 3, TimeBase: media.TimeBase{Numerator: 1, Denominator: 30}, Video: actual}, headers)
			if err != nil {
				t.Fatal(err)
			}
			packet, err = media.NewPacket(media.PacketInfo{DurationTicks: 1}, mismatch, au)
			if err != nil {
				t.Fatal(err)
			}
			if _, err = inspector.Inspect(packet); err == nil {
				t.Fatal("Принята ложная глубина конфигурации")
			}
		})
	}
}

// TestSDRHeadersRejectTruncationAndContradictoryDescriptors проверяет все байтовые обрывы
// реальных av1C/avcC, поля глубины/субдискретизации и дублирование префикса SPS в avcC.
func TestSDRHeadersRejectTruncationAndContradictoryDescriptors(t *testing.T) {
	// fixture выбирает реальную конфигурацию из всей программной матрицы.
	for _, fixture := range encodedSDRFixtures() {
		// headers и err содержат полную конфигурацию и возможную ошибку hex-эталона.
		headers, err := hex.DecodeString(fixture.config)
		if err != nil {
			t.Fatal(err)
		}
		// length выбирает каждый усечённый префикс конфигурации.
		for length := range len(headers) {
			if fixture.codec == core.CodecAV1 {
				if _, err = ParseAV1Config(headers[:length]); err == nil {
					t.Fatalf("Принят обрыв av1C %s/%d", fixture.pixel, length)
				}
			} else {
				// optionalBoundary допускает прежний avcC без всех четырёх байтов необязательного расширения.
				optionalBoundary := headers[1] != 66 && headers[1] != 77 && length == len(headers)-4
				if _, err = H264SPS(VideoDescription{Headers: headers[:length], Width: 128, Height: 128}); err == nil && !optionalBoundary {
					t.Fatalf("Принят обрыв avcC %s/%d", fixture.pixel, length)
				}
			}
		}
		if fixture.codec == core.CodecH264 {
			// offset выбирает каждое дублируемое поле профиля, ограничений совместимости либо уровня в avcC.
			for _, offset := range []int{1, 2, 3} {
				// bad содержит конфигурацию с префиксом, противоречащим неизменённому SPS.
				bad := bytes.Clone(headers)
				bad[offset] ^= 1
				if _, err = H264SPS(VideoDescription{Headers: bad, Width: 128, Height: 128}); err == nil {
					t.Fatal("Префикс avcC подменил SPS")
				}
			}
			if headers[1] != 66 && headers[1] != 77 {
				// offset выбирает субдискретизацию, глубину яркости и глубину цветности в расширении avcC.
				for offset := len(headers) - 4; offset < len(headers)-1; offset++ {
					// bad изменяет только отдельный дескриптор при прежнем фактическом SPS.
					bad := bytes.Clone(headers)
					bad[offset] ^= 1
					if _, err = H264SPS(VideoDescription{Headers: bad, Width: 128, Height: 128}); err == nil {
						t.Fatal("Расширение avcC подменило SPS")
					}
				}
			}
		}
	}
}

// TestH264TenBitLosslessPPSUsesDepthDependentQP проверяет настоящий avcC libx264/High444/10-bit
// с QP0. Его PPS содержит допустимое начальное смещение ниже восьмибитного предела −26;
// SPS сигнализирует qpprime_y_zero_transform_bypass_flag. Файл FFmpeg7.1.5 отдельно декодирован с -xerror.
func TestH264TenBitLosslessPPSUsesDepthDependentQP(t *testing.T) {
	// headers содержит исходные SPS/PPS и расширение avcC без изменения отдельных полей.
	headers := aacHex(t, "01f4000bffe1001d67f4000b90dd640811b016a0808088000003000800000301e078a1524001000668ebc026f2c0fffafa00")
	// s и err содержат разобранный SPS и результат полной проверки PPS/расширения.
	s, err := H264SPS(VideoDescription{Headers: headers, Width: 128, Height: 128})
	if err != nil || !s.QpprimeYZeroTransformBypassFlag || s.ChromaFormatIdc != 3 || s.BitDepthLumaMinus8 != 2 {
		t.Fatal("Настоящий 10-bit lossless PPS не принят", s, err)
	}
}
